// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint256 priorPlays) public {
        vm.assume(actor != address(0));
        priorPlays = bound(priorPlays, 0, 10);

        uint256 TICKET = 10;
        vm.deal(actor, (priorPlays + 1) * TICKET + 1 ether);

        for (uint256 i = 0; i < priorPlays; i++) {
            vm.prank(actor);
            c.play{value: TICKET}();
        }

        uint256 potBefore = c.pot();

        vm.prank(actor);
        c.play{value: TICKET}();

        uint256 potAfter = c.pot();

        assertTrue(potAfter == 0 || potAfter == potBefore + TICKET);
    }
}
